  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    if (input.parentId === issue.id) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    const parent = await requireLiveParent(
      input.orgId,
      issue.projectId,
      input.parentId,
    );

    const tree = await issueRepo.listProjectIssueTree(
      input.orgId,
      issue.projectId,
    );
    if (descendantsOf(tree, issue.id).some((row) => row.id === parent.id)) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    const deepest =
      levelOf(indexById(tree), parent) + 1 + heightBelow(tree, issue.id);
    if (deepest > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }

  if (issue.parentId === input.parentId) return issue;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct, live sub-issues of an issue, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listChildIssues(orgId, issue.id);
}

/** Open/closed counts over every live issue below an issue, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const tree = await issueRepo.listProjectIssueTree(orgId, issue.projectId);
  const live = descendantsOf(tree, issue.id).filter(
    (row) => row.archivedAt === null,
  );
  const open = live.filter((row) => isOpen(row.status)).length;

  return { total: live.length, open, closed: live.length - open };
}

