function isOpen(status: IssueStatus): boolean {
  return !CLOSED_ISSUE_STATUSES.includes(status);
}

/** A parent must be a live issue of the same project and workspace. */
async function requireLiveParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

function indexById(tree: readonly Issue[]): ReadonlyMap<IssueId, Issue> {
  return new Map(tree.map((row) => [row.id, row]));
}

function childrenByParent(
  tree: readonly Issue[],
): ReadonlyMap<IssueId, readonly Issue[]> {
  const map = new Map<IssueId, Issue[]>();
  for (const row of tree) {
    if (row.parentId === null) continue;
    const list = map.get(row.parentId) ?? [];
    list.push(row);
    map.set(row.parentId, list);
  }
  return map;
}

/** Every issue below `issueId`, at any depth, archived ones included. */
function descendantsOf(tree: readonly Issue[], issueId: IssueId): Issue[] {
  const children = childrenByParent(tree);
  const seen = new Set<IssueId>([issueId]);
  const out: Issue[] = [];
  const queue: IssueId[] = [issueId];
  while (queue.length > 0) {
    const current = queue.shift() as IssueId;
    for (const child of children.get(current) ?? []) {
      if (seen.has(child.id)) continue;
      seen.add(child.id);
      out.push(child);
      queue.push(child.id);
    }
  }
  return out;
}

/** Level of an issue in its tree; a root issue is level 0. */
function levelOf(byId: ReadonlyMap<IssueId, Issue>, issue: Issue): number {
  const seen = new Set<IssueId>([issue.id]);
  let level = 0;
  let parentId = issue.parentId;
  while (parentId !== null && !seen.has(parentId)) {
    const parent = byId.get(parentId);
    if (!parent) break;
    seen.add(parentId);
    level += 1;
    parentId = parent.parentId;
  }
  return level;
}

/** How many levels sit below `issueId` (0 when it has no sub-issues). */
function heightBelow(tree: readonly Issue[], issueId: IssueId): number {
  const children = childrenByParent(tree);
  const seen = new Set<IssueId>([issueId]);
  let height = 0;
  let frontier: IssueId[] = [issueId];
  while (frontier.length > 0) {
    const next: IssueId[] = [];
    for (const id of frontier) {
      for (const child of children.get(id) ?? []) {
        if (seen.has(child.id)) continue;
        seen.add(child.id);
        next.push(child.id);
      }
    }
    if (next.length > 0) height += 1;
    frontier = next;
  }
  return height;
}

/**
 * Called after `closed` stopped being open. Tells the direct parent's
 * assignee once nothing below the parent is open any more.
 */
async function announceIfSubIssuesCompleted(
  actor: Actor,
  closed: Issue,
): Promise<void> {
  if (closed.parentId === null) return;

  const parent = await issueRepo.findIssueById(closed.orgId, closed.parentId);
  if (parent === null || parent.archivedAt !== null) return;
  if (parent.assigneeId === null) return;

  const tree = await issueRepo.listProjectIssueTree(
    parent.orgId,
    parent.projectId,
  );
  const stillOpen = descendantsOf(tree, parent.id).some(
    (row) => row.archivedAt === null && isOpen(row.status),
  );
  if (stillOpen) return;

  await notify(parent.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues are closed",
    body: `Every sub-issue of issue ${parent.id} is now closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}
