  const c3 = await mk("c3", c2.id);
  await expect(mk("c4", c3.id)).rejects.toMatchObject({ reason: "too_deep" });
  const x = await mk("x"); const y = await mk("y", x.id);
  await expect(issueService.setIssueParent(a, { orgId: t.org.id, issueId: x.id, parentId: c2.id })).rejects.toMatchObject({ reason: "too_deep" });
