  expect(await issueService.getIssueRollup(a, t.org.id, root.id)).toEqual({ total: 5, open: 5, closed: 0 });
  await issueService.setIssueParent(a, { orgId: t.org.id, issueId: x.id, parentId: null });
  await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: c3.id, status: "done" });
  await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: c2.id, status: "done" });
  expect(getDb().select().from(notifications).all().filter(n => n.kind === "sub_issues_completed").length).toBe(0);
  await issueService.archiveIssue(a, t.org.id, c1.id);
  const ns = getDb().select().from(notifications).all().filter(n => n.kind === "sub_issues_completed");
  expect(ns.length).toBe(1);
  expect(await issueService.getIssueRollup(a, t.org.id, root.id)).toEqual({ total: 0, open: 0, closed: 0 });
  void y;
});
